import 'package:flutter/material.dart';import 'api.dart';import 'catalog.dart' as catalog;import 'cart.dart';
void main()=>runApp(const DadoHomeApp());const dadoRed=Color(0xFFE30613);class DadoHomeApp extends StatelessWidget{const DadoHomeApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'ДАДО Home',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:dadoRed),useMaterial3:true),home:const LoginScreen());}
class LoginScreen extends StatefulWidget{const LoginScreen({super.key});@override State<LoginScreen> createState()=>_LoginScreenState();}class _LoginScreenState extends State<LoginScreen>{final phone=TextEditingController();bool busy=false;Future<void> send()async{setState(()=>busy=true);try{final full='+992${phone.text.replaceAll(' ','')}';final dev=await ApiClient.instance.requestOtp(full);if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>OtpScreen(phone:full,devCode:dev)));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Spacer(),const Icon(Icons.shopping_bag_rounded,size:72,color:dadoRed),const Text('ДАДО',textAlign:TextAlign.center,style:TextStyle(fontSize:42,fontWeight:FontWeight.w900,color:dadoRed)),const Text('Товары для дома',textAlign:TextAlign.center),const Spacer(),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(prefixText:'+992 ',labelText:'Номер телефона',border:OutlineInputBorder())),const SizedBox(height:12),FilledButton(onPressed:busy?null:send,child:Text(busy?'Отправка...':'Получить код')),const Spacer()]))));}
class OtpScreen extends StatefulWidget{final String phone;final String? devCode;const OtpScreen({super.key,required this.phone,this.devCode});@override State<OtpScreen> createState()=>_OtpScreenState();}class _OtpScreenState extends State<OtpScreen>{final code=TextEditingController();bool busy=false;Future<void> verify()async{setState(()=>busy=true);try{await ApiClient.instance.verifyOtp(widget.phone,code.text);if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const HomeShell()),(_)=>false);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Неверный или просроченный код')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(),body:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('Подтверждение входа',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),Text('Код отправлен на ${widget.phone}'),if(widget.devCode!=null)Text('DEV OTP: ${widget.devCode}'),const SizedBox(height:18),TextField(controller:code,maxLength:6,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Код OTP',border:OutlineInputBorder())),FilledButton(onPressed:busy?null:verify,child:const Text('Подтвердить'))])));}
class HomeShell extends StatefulWidget{const HomeShell({super.key});@override State<HomeShell> createState()=>_HomeShellState();}class _HomeShellState extends State<HomeShell>{int index=0;final pages=const[HomePage(),catalog.CatalogPage(),CartPage(),OrdersPage(),ProfilePage()];@override Widget build(BuildContext context)=>Scaffold(body:pages[index],bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Главная'),NavigationDestination(icon:Icon(Icons.grid_view),label:'Каталог'),NavigationDestination(icon:Icon(Icons.shopping_cart_outlined),label:'Корзина'),NavigationDestination(icon:Icon(Icons.receipt_long_outlined),label:'Заказы'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Профиль')]));}
class HomePage extends StatelessWidget{const HomePage({super.key});@override Widget build(BuildContext context)=>const SafeArea(child:Padding(padding:EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('ДАДО',style:TextStyle(fontSize:30,fontWeight:FontWeight.w900,color:dadoRed)),Text('Товары для дома'),SizedBox(height:20),Text('Каталог, акции и новинки',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold))])));}
class OrdersPage extends StatefulWidget{const OrdersPage({super.key});@override State<OrdersPage> createState()=>_OrdersPageState();}class _OrdersPageState extends State<OrdersPage>{late Future<List<dynamic>> f;@override void initState(){super.initState();f=ApiClient.instance.myOrders();}@override Widget build(BuildContext context)=>SafeArea(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Мои заказы',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),Expanded(child:FutureBuilder<List<dynamic>>(future:f,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:TextButton(onPressed:()=>setState(()=>f=ApiClient.instance.myOrders()),child:const Text('Повторить загрузку')));final a=s.data??[];if(a.isEmpty)return const Center(child:Text('Заказов пока нет'));return ListView.builder(itemCount:a.length,itemBuilder:(context,i){final o=a[i];return Card(child:ListTile(title:Text(o['number']??'Заказ'),subtitle:Text('Статус: ${o['status']}'),trailing:Text('${o['total']} с.')));});}))])));}
class ProfilePage extends StatelessWidget{const ProfilePage({super.key});@override Widget build(BuildContext context)=>const SafeArea(child:Padding(padding:EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Личный кабинет',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),ListTile(leading:Icon(Icons.account_balance_wallet),title:Text('DADO Wallet')),ListTile(leading:Icon(Icons.credit_card),title:Text('Способы оплаты')),ListTile(leading:Icon(Icons.security),title:Text('Безопасность и 2FA'))])));}
